    ResourceCategory(id: "business_10_poultry_farming", section: ResourceSection.business, number: 10, name: "Poultry Farming", searchKeywords: ["poultry farmer", "chicken farming", "egg business", "poultry business", "chicken business", "poultry farm"], businessQA: <BusinessQA>[BusinessQA(question: "How does this business make money in the real world?", answer: "Sells live birds, dressed meat, or eggs to households, restaurants, and retailers."), BusinessQA(question: "Who actually pays, and why?", answer: "Households (protein staple), restaurants/hotels, and food vendors buying in bulk."), BusinessQA(question: "What problem does it solve for the customer?", answer: "Solves a steady protein-supply need in a market where chicken/egg demand is constant."), BusinessQA(question: "How does it attract and keep customers?", answer: "Consistent supply and quality, competitive pricing at harvest time, direct bulk-buyer relationships."), BusinessQA(question: "What tools, systems, or platforms does it need to run and earn?", answer: "Housing/pen, feed, clean water, a vaccination schedule, a vet relationship."), BusinessQA(question: "How is the price/value set?", answer: "Priced against the prevailing market rate at sale time, which swings with feed cost and disease."), BusinessQA(question: "What turns it from a hustle into a real business?", answer: "Moving from backyard-scale to structured cycles timed to market demand, with proper records."), BusinessQA(question: "What assets can be built from it?", answer: "The flock/breeding stock, land/housing infrastructure, buyer relationships."), BusinessQA(question: "Where do people in this business commonly lose money?", answer: "Disease outbreaks wiping out a flock, poor feed-cost tracking, selling at the wrong time."), BusinessQA(question: "How does it build long-term wealth, not just daily income?", answer: "Reinvest into feed production or hatchery — owning more of the value chain instead of only selling grown birds.")]),
